#!/usr/bin/env python3
"""undefined-sentinel-among-numbers.py <seed>: among raw numbers a marker stands for undefined (an element beyond the end, an optional member). HERE MARKER, DEED AND PLACE STAND IN ONE FUNCTION, as text: `const m = values[i + 9]; const n = m + 1;` and n is led into a place that has room for a marker again. It must read NaN there."""
import random, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
R = random.Random(seed)
MARKERS = ['values[i + 9]', 'fractions[i + 9]', 'f64[i + 5]', 'holes[i + 1]', 'values[-1 - i]', 'wholes[i + 3]']
DEEDS = ['m + 1', 'm * 2', 'm - 0.5', 'm / 3', '-m', 'm + m', 'm % 2', 'm ** 2', 'Math.abs(m)', 'Math.sqrt(m)', 'Math.floor(m)', 'Math.max(m, 1)', 'Math.min(1, m)', 'Math.fround(m)', 'Math.round(m)', 'Math.trunc(m)', '+m', '1 - m', 'm + i', 'm * i', '(m + 1) * 2 - 3', 'm - m', 'i + 0.5 + m']
PLACES = ['return n;', 'return flag ? n : m;', 'return flag ? m : n;', 'let x = m; if (flag) x = n; return x;', 'let x: number | undefined = undefined; if (flag) x = n; return x;', 'let x: number | null = null; if (flag) x = n; return x;', 'return (n as number | undefined) ?? 5;', 'return (n as unknown) === undefined;', 'return (n as unknown) == null;', 'return typeof n;',
  'return rest(n, 1.5);', 'return rest(n, m, n);', 'return rest(m, n);', 'return rest(n);', 'return restOr(n, m);', 'return optional(n);', 'return withDefault(n);', 'const a: number[] = [n, m, 1.5]; return (0 in a) + show(a[0]) + show(a[1]);', 'const a: number[] = [m, n]; return (0 in a) + "" + (1 in a) + show(a[0]) + show(a[1]);', 'const a: (number | undefined)[] = [n]; return show(a[0]) + a.includes(undefined);', 'const a: number[] = [0.5]; a.push(n); return (1 in a) + show(a[1]);', 'const a: number[] = [0.5, 1.5]; a[0] = n; return (0 in a) + show(a[0]);',
  'const b: Box = { n: 1, o: n, m: n, z: n }; return show(b.o) + show(b.m) + show(b.z) + ("o" in b) + Object.keys(b).length;', 'const b: Box = { n: 1, m: 1, z: 1 }; b.o = n; b.m = n; b.z = n; b.n = n; return show(b.o) + show(b.m) + show(b.z) + show(b.n) + ("o" in b);', 'return ((): number | undefined => n)();', 'return ((): number | null => n)();', 'let held: number | undefined = undefined; const set = (): void => { held = n; }; set(); return show(held);', 'const t: [number, number?] = [1, n]; return show(t[1]) + t.length;', 'return JSON.stringify({ n, a: [n] });', 'const k = new Kept(n); k.o = n; k.z = n; return show(k.first) + show(k.o) + show(k.z);', 'let s: number | undefined = m; for (let k = 0; k < 2; k++) s = flag ? n : s; return s;', 'return [n, m].map(show).join();', 'return sum3(n, m, 1);', 'f64[0] = n; return f64[0];',
  'return rest(flag ? n : m, 1.5);', 'const x = flag ? n : m; return rest(x, x);', 'const x = flag ? m : n; return rest(1.5, x);', 'const a: number[] = [flag ? n : m, 0.5]; return (0 in a) + show(a[0]);', 'let x = m; if (flag) x = n; return rest(x);', 'let x = n; for (let k = 0; k < 2; k++) x = flag ? x : m; return rest(x, n, m);', 'const x = flag ? n : m; return sum3(x, 1, 2);', 'const x = flag ? n : m; const a: number[] = [x, x, x, x, x, x, x, x, x, x, x, x, x, x, x, x, x]; return a.map(show).join("") + (16 in a);',
  'return rest(flag ? n : m, 1.5);', 'const x = flag ? n : m; return rest(x, x);', 'const x = flag ? m : n; return rest(1.5, x);', 'let x = m; if (flag) x = n; return rest(x);']
out = ['// generated by undefined-sentinel-among-numbers.py %d' % seed, 'declare const console: { log(...values: unknown[]): void };',
 'const show = (v: unknown): string => (v === null ? "null" : v === undefined ? "u" : typeof v === "number" ? (Object.is(v, -0) ? "-0" : String(v)) : String(v));',
 'const values: number[] = [1, 2, 3]; const wholes: number[] = [1, 2]; const fractions: number[] = [0.5, 1.5]; const holes: number[] = [0.5, , 2.5] as number[]; const f64 = new Float64Array(2);',
 'interface Box { n: number; o?: number; m: number | undefined; z: number | null }', 'class Kept { o: number | undefined = undefined; z: number | null = null; constructor(public first: number) {} }',
 'function rest(...xs: number[]): string { let own = ""; for (let k = 0; k < xs.length; k++) own += k in xs ? "1" : "0"; return own + " " + xs.map(show).join(); }', 'function restOr(...xs: (number | undefined | null)[]): string { return xs.map(show).join(); }',
 'function optional(a?: number): string { return show(a) + (a === undefined ? " absent" : " there"); }', 'function withDefault(a: number = 7): string { return show(a); }', 'function sum3(...xs: number[]): string { let t = 0; for (let k = 0; k < xs.length; k++) t += xs[k]!; return show(t) + xs.length; }']
rows = []
for n in range(260):
    m, d, p = R.choice(MARKERS), R.choice(DEEDS), R.choice(PLACES)
    out.append('function t%d(i: number, flag: boolean): unknown { const m = %s; const n = %s; %s }' % (n, m, d, p)); rows.append((n, m, d, p))
out.append('const ALL: [string, (i: number, flag: boolean) => unknown][] = [%s];' % ', '.join('[%s, t%d]' % (repr('%s ; %s ; %s' % (m, d, p)).replace("'", '"') if '"' not in p + d + m else '`%s ; %s ; %s`' % (m, d, p), n) for n, m, d, p in rows))
out.append('for (let turn = 0; turn < 3; turn++) for (const [name, f] of ALL) for (const flag of [true, false]) { let answer: string; try { answer = show(f(0, flag)); } catch (e) { answer = "THROWS " + (e as Error).name; } if (turn === 2) console.log(name + " " + flag + ": " + answer); }')
print('\n'.join(out))
